ipcMain.handle('vault:lock', () => {
  getVault().lock()
  return getVault().status(actorOrUndefined())
})
// Works when the licence has run out (security housekeeping), never when the change wouldn't be saved.
// Not wrapped: the vault re-seals everything in its own transaction, and a wrong passphrase's entry stays.
ipcMain.handle('vault:change-passphrase', (_e, current: unknown, next: unknown) => result(() => {
  const actor = currentActor()
  const refusal = storageRefusal()
  if (refusal) throw new UserFacingError(refusal)
  if (typeof current !== 'string' || typeof next !== 'string' || current.length > 1000 || next.length > 1000) {
    throw new UserFacingError('Type the current passphrase and the new one.')
  }
  return getVault().changePassphrase(current, next, actor, auditAs(actor))
}))
